// Isolated browser contract checks: mocked API is explicitly NOT end-to-end evidence.
const {test,before,after}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE);const root=path.resolve(__dirname,'../..'),origin='https://transfer.example.test';let browser;
before(async()=>browser=await chromium.launch({channel:'chrome',headless:true}));after(async()=>browser?.close());
const lifecycle={vehicle_id:1,state:'active',actions:['sold','deposited'],ownership_id:11,version:1,ownership_token:'a'.repeat(64),sale_details_version:2};
async function fixture({respond,state=lifecycle,role='user'}={}){const context=await browser.newContext({viewport:{width:390,height:844}}),requests=[];await context.route('**/*',async route=>{const url=new URL(route.request().url()),r=route.request();if(url.origin!==origin)return route.abort();if(['/web/vehicle-transfers.js','/web/referral-features.css'].includes(url.pathname))return route.fulfill({contentType:url.pathname.endsWith('.css')?'text/css':'text/javascript',body:fs.readFileSync(path.join(root,url.pathname))});if(url.pathname==='/fixture')return route.fulfill({contentType:'text/html',body:`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/web/referral-features.css"></head><body><button id="manage">Správa</button><script src="/web/vehicle-transfers.js"></script><script>let generation=0;window.AdminBrowserSession={token:()=> 'SYNTHETIC',snapshot:()=>({generation}),assertCurrent:s=>{if(s.generation!==generation)throw new DOMException('changed','AbortError')},request:(url,init,s)=>{AdminBrowserSession.assertCurrent(s);return fetch(url,init)},change:()=>{generation++;dispatchEvent(new Event('admin-session-ended'));}};document.getElementById('manage').onclick=()=>VehicleTransfers.openManagement(1);</script></body></html>`});const req={path:url.pathname,method:r.method(),body:r.postDataJSON()};requests.push(req);if(respond&&await respond(route,req))return;if(url.pathname==='/user/me')return route.fulfill({json:{id:1,role,email:'seller@example.invalid'}});if(url.pathname==='/api/v1/vehicles/1/lifecycle')return route.fulfill({json:state});return route.fulfill({status:404,json:{detail:'Mock only'}});});const page=await context.newPage();await page.goto(origin+'/fixture');return {context,page,requests};}
async function sale(f){await f.page.getByRole('button',{name:'Správa',exact:true}).click();await f.page.getByRole('button',{name:'Prodat vozidlo',exact:true}).click();}
async function confirm(f){await f.page.locator('.referral-confirm').getByRole('button',{name:'Potvrdit prodej',exact:true}).click();}
test('required recipient/outside reason, final confirmation, and uncertain-write retry retain one UUID',async()=>{let attempt=0;const f=await fixture({respond:async(route,r)=>{if(r.method==='POST'){attempt++;await (attempt===1?route.fulfill({status:503,json:{detail:'Temporarily unavailable'}}):route.fulfill({json:{vehicle_id:1,action:'sold',state:'archived',message:'Uloženo'}}));return true;}return false;}});try{await sale(f);await f.page.getByRole('button',{name:'Pokračovat k potvrzení prodeje'}).click();await f.page.getByRole('alert').filter({hasText:'platný e-mail'}).waitFor();assert.equal(f.requests.filter(r=>r.method==='POST').length,0);await f.page.getByLabel('Způsob prodeje').selectOption('outside_app');await f.page.getByRole('button',{name:'Pokračovat k potvrzení prodeje'}).click();await f.page.getByRole('alert').filter({hasText:'Vyberte důvod'}).waitFor();await f.page.getByLabel('Důvod prodeje mimo aplikaci').selectOption('other');await f.page.getByLabel('Stručně popište důvod').fill('Prodej mimo dostupnou oblast');await f.page.getByRole('button',{name:'Pokračovat k potvrzení prodeje'}).click();assert.equal(f.requests.filter(r=>r.method==='POST').length,0);await confirm(f);await f.page.getByRole('button',{name:'Znovu odeslat stejný požadavek'}).waitFor();assert.equal(await f.page.locator('dialog:not(.referral-confirm)').getByRole('button',{name:'Zavřít',exact:true}).isDisabled(),true);await f.page.getByRole('button',{name:'Znovu odeslat stejný požadavek'}).click();await f.page.getByRole('heading',{name:'Změna potvrzena'}).waitFor();const posts=f.requests.filter(r=>r.method==='POST');assert.equal(posts.length,2);assert.deepEqual(posts[0].body,posts[1].body);assert.match(posts[0].body.client_id,/^[0-9a-f-]{36}$/);assert.equal(posts[0].body.sale.mode,'outside_app');assert.equal(posts[0].body.sale.buyer_email,undefined);assert.equal(await f.page.locator('dialog').evaluate(el=>el.scrollWidth<=el.clientWidth),true);}finally{await f.context.close();}});
test('account change during final confirmation closes private UI and prevents the write',async()=>{const f=await fixture();try{await sale(f);await f.page.getByLabel('E-mail nového majitele · povinné').fill('buyer@example.invalid');await f.page.getByRole('button',{name:'Pokračovat k potvrzení prodeje'}).click();await f.page.locator('.referral-confirm').waitFor();await f.page.evaluate(()=>AdminBrowserSession.change());await f.page.waitForFunction(()=>!document.querySelector('dialog'));assert.equal(f.requests.filter(r=>r.method==='POST').length,0);}finally{await f.context.close();}});
test('older server lacking sale v2 cannot submit a sale without supported consent flow',async()=>{const f=await fixture({state:{...lifecycle,sale_details_version:undefined}});try{await sale(f);assert.equal(await f.page.getByRole('button',{name:'Pokračovat k potvrzení prodeje'}).isDisabled(),true);assert.match(await f.page.locator('dialog').innerText(),/ještě není na serveru dostupný/);assert.equal(f.requests.filter(r=>r.method==='POST').length,0);}finally{await f.context.close();}});
test('customer cannot open administrator verification even with direct function invocation',async()=>{const f=await fixture();try{await f.page.evaluate(()=>VehicleTransfers.openAdminReview(1));await f.page.getByRole('alert').filter({hasText:'pouze administrátorovi'}).waitFor();assert.equal(f.requests.some(r=>r.path.includes('/admin/')),false);}finally{await f.context.close();}});
